    @property
    def basepath(self):
        """generate the basepath value"""
        self._ensure_build_identity()
        return self._get_basepath()

    def _get_basepath(self):
        """Compose the base path used for emitted files."""
        folder = self._plain_name
        if self._build_hash is not None:
            folder = f"{folder}_{self._build_hash}"
        build_root = self.general_configuration.get_nested(
            "paths", "build_root", default=type(self).BUILD_ROOT
        )
        return str(Path(build_root) / folder)

    @property
    def filename(self):
        """generate the filename value"""
        self._ensure_build_identity()
        return self._get_filename()

    def _get_filename(self):
        """Compose the primary source filename."""
        return f"{self.libname}.{self.fileending}"

    def locate_python_module(self):
        """
        Return the importable Python module artifact if this library exposes one.

        The generic implementation supports generated Python source files. Other
        backends should override this method when they produce importable shared
        libraries or different artifact layouts.
        """
        filename = Path(self.relative_to_basepath(self.filename))
        if filename.suffix == ".py":
            return str(filename)
        return None

    def import_python_module(self):
        """
        Import and return the generated Python module for this library.

        Backends that emit importable non-Python artifacts should override
        :meth:`locate_python_module` and, if needed, this method itself.
        """
        module_path = self.locate_python_module()
        if module_path is None:
            raise NotImplementedError(
                f"{type(self).__name__} does not provide an importable Python "
                f"module artifact"
            )
        resolved_module_path = Path(module_path).resolve()
        if not resolved_module_path.exists():
            raise ImportError(
                f"generated Python module was not found at {resolved_module_path}"
            )
        spec = importlib.util.spec_from_file_location(
            self.libname,
            resolved_module_path,
        )
        if spec is None or spec.loader is None:
            raise ImportError(
                f"cannot create import spec for {resolved_module_path}"
            )
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    @property
    def docname(self):
        """generate the docname value"""
        self._ensure_build_identity()
        return self._get_docname()

    def _get_docname(self):
        """Compose the documentation sidecar filename."""
        suffix = self.general_configuration.get_nested(
            "paths", "doc_suffix", default="_doc.txt"
        )
        return f"{self.libname}{suffix}"

    @property
    def makefilename(self):
        """Return the per-library makefile path."""
        self._ensure_build_identity()
        return self._get_makefilename()

    def _get_makefilename(self):
        """Compose the per-library makefile filename."""
        return self.general_configuration.get_nested(
            "paths", "makefile_name", default="Makefile"
        )

    @property
    def manifestname(self):
        """Return the manifest path for this library build."""
        self._ensure_build_identity()
        return self.general_configuration.get_nested(
            "paths",
            "manifest_name",
            default="library_manifest.json",
        )

    @property
    def logname(self):
        """Return the build log path for this library build."""
        self._ensure_build_identity()
        return self.general_configuration.get_nested(
            "paths", "build_log_name", default="build.log"
        )

