    def get_makefile_compile_dependency_targets(self):
        """Yield targets required to compile this library's sources."""
        for dependency in self.get_dependencies(recursive=False):
            target = dependency.get_header_target()
            if target is None:
                target = dependency.get_codefile_target()
            if target is not None:
                yield target

    def get_makefile_dependency_targets(self):
        """Yield targets required to link this library."""
        for dependency in self.get_dependencies(recursive=False):
            target = dependency.get_library_target()
            if target is None:
                target = dependency.get_codefile_target()
            if target is not None:
                yield target

    def get_makefile_targets(self):
        """Yield all makefile targets contributed by this library."""
        code_target = self.get_codefile_target()
        if code_target is not None:
            yield code_target
        library_target = self.get_library_target()
        if library_target is not None:
            yield library_target

    def get_library_target(self):
        return None

    def get_execution_target(self):
        """Return the target that should be executed for compilation."""
        return self.get_library_target()

    def get_header_target(self):
        return None

    def get_codefile_target(self):
        return MFTSource(self.relative_to_basepath(self.filename))
